let role=null,auth=sessionStorage.mbToken||'',selected=null,clients=[],tab='summary';
let kbOriginalContent='',kbDirty=false,kbState=[];
const $=id=>document.getElementById(id);const wait=ms=>new Promise(r=>setTimeout(r,ms));const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function toast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');setTimeout(()=>$('toast').classList.add('hidden'),2600)}

const loadingMeta={
  overview:['overview','Menyusun overview admin','Menghitung client, WhatsApp, reply rate, dan grafik semua tenant.'],
  clients:['clients','Memuat manajemen client','Menyiapkan form client, status WhatsApp, analytics, dan kartu operational monitor.'],
  settings:['settings','Membuka admin settings','Menyiapkan kontrol service bot dan pengaturan akses dashboard.'],
  clientHome:['dashboard','Menyusun dashboard client','Mengambil performa WhatsApp, ringkasan bisnis, dan status operasional terbaru.'],
  clientAnalytics:['analytics','Mengolah analytics','Membaca tren pesan, reply rate, kontak aktif, dan percakapan yang perlu dicek.'],
  clientCustomers:['customers','Memuat data customer','Menyiapkan CRM ringan, filter, pencarian, dan daftar percakapan terbaru.'],
  clientPair:['whatsapp','Menyiapkan WhatsApp pairing','Mengecek session, QR, nomor terhubung, dan status service bot.'],
  clientKb:['knowledge','Membuka card knowledge','Menyusun section editor, status perubahan, dan panel kualitas knowledge.'],
  clientOps:['ops','Memuat operasional bot','Menyiapkan checklist live, aturan aman, grafik, dan standar handoff admin.'],
  clientSettings:['settings','Memuat settings client','Mengambil profil bisnis, status WhatsApp, dan panduan maintenance.'],
  archive:['danger','Mengarsipkan client','Memperbarui status client tanpa menghapus data tenant yang tersimpan.'],
  disconnect:['whatsapp danger','Memutuskan WhatsApp','Membersihkan session, file pairing, dan status koneksi tenant.']
};
function loadingPattern(v){const bars='<div class="load-bars"><span></span><span></span><span></span><span></span><span></span></div>';const cards='<div class="load-card-grid"><span></span><span></span><span></span><span></span></div>';const rows='<div class="load-rows"><span></span><span></span><span></span><span></span></div>';const kb='<div class="load-kb"><span></span><span></span><span></span></div>';const ops='<div class="load-checks"><span></span><span></span><span></span></div>';if(v.includes('analytics')||v.includes('overview')||v.includes('dashboard'))return bars;if(v.includes('clients')||v.includes('customers')||v.includes('whatsapp')||v.includes('settings'))return cards;if(v.includes('knowledge'))return kb;if(v.includes('ops'))return ops;if(v.includes('danger'))return rows;return rows}
function loadingBlock(text='Memuat data...',sub='Mohon tunggu sebentar.',variant='default'){return `<section class="loading-screen loading-${esc(variant).replace(/\s+/g,' loading-')}" aria-live="polite"><div class="loading-card"><div class="loading-kicker">Muy Business</div><div class="loading-line"><span>${esc(text)}</span></div><p class="loading-sub">${esc(sub)}</p>${loadingPattern(variant)}</div></section>`}
function setViewLoading(text='Memuat data...',sub='Dashboard sedang menyiapkan data terbaru.',variant='default'){view.innerHTML=loadingBlock(text,sub,variant)}
function setRouteLoading(id){const m=loadingMeta[id]||['default','Memuat halaman','Dashboard sedang menyiapkan data terbaru.'];setViewLoading(m[1],m[2],m[0])}

async function withButton(btn,text,job){const b=btn||document.activeElement;const old=b&&b.tagName==='BUTTON'?b.textContent:'';if(b&&b.tagName==='BUTTON'){b.classList.add('busy');b.disabled=true;if(text)b.textContent=text}try{return await job()}finally{if(b&&b.tagName==='BUTTON'){b.classList.remove('busy');b.disabled=false;if(text)b.textContent=old}}}
async function api(url,opt={}){const r=await fetch(url,{headers:{'Content-Type':'application/json',...(auth?{Authorization:'Bearer '+auth}:{})},...opt});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Request gagal');return j}
function confirmBox({title='Konfirmasi',message='',confirmText='Lanjutkan',cancelText='Batal',danger=false}={}){return new Promise(resolve=>{modalRoot.className='modal-backdrop';modalRoot.innerHTML=`<div class="modal"><div class="modal-head"><h3>${esc(title)}</h3><p class="muted">${esc(message)}</p></div><div class="modal-actions"><button class="ghost" id="mc">${esc(cancelText)}</button><button class="${danger?'danger':''}" id="mo">${esc(confirmText)}</button></div></div>`;const close=v=>{modalRoot.className='hidden';modalRoot.innerHTML='';resolve(v)};mc.onclick=()=>close(false);mo.onclick=()=>close(true);modalRoot.onclick=e=>{if(e.target===modalRoot)close(false)}})}
async function loginUnified(){return withButton(document.activeElement,'Masuk...',async()=>{const identifier=loginSlug.value.trim(),password=loginPass.value;try{let r;if(identifier.toLowerCase()==='admin'){r=await api('/api/auth/admin/login',{method:'POST',body:JSON.stringify({username:identifier,password})});role='admin';sessionStorage.removeItem('mbSlug')}else{r=await api('/api/auth/client/login',{method:'POST',body:JSON.stringify({slug:identifier,password})});role='client';sessionStorage.mbSlug=r.slug}auth=r.token;sessionStorage.mbToken=auth;sessionStorage.mbRole=role;showApp()}catch(e){toast(identifier.toLowerCase()==='admin'?'Username/password admin salah':'Login client salah')}})}

function applySidebarState(){const collapsed=localStorage.mbSidebarCollapsed==='1';document.body.classList.toggle('sidebar-collapsed',collapsed);const btn=document.querySelector('.side-toggle');if(btn){btn.textContent=collapsed?'›':'‹';btn.title=collapsed?'Perbesar sidebar':'Perkecil sidebar';btn.setAttribute('aria-label',btn.title)}}
function toggleSidebar(){localStorage.mbSidebarCollapsed=localStorage.mbSidebarCollapsed==='1'?'0':'1';applySidebarState()}
window.toggleSidebar=toggleSidebar;
document.addEventListener('DOMContentLoaded',applySidebarState);
function logout(){sessionStorage.clear();auth='';role=null;$('login').classList.remove('hidden');$('app').classList.add('hidden')}async function askLogout(){if(await confirmBox({title:'Keluar dari dashboard?',message:'Sesi login di browser ini akan dihapus.',confirmText:'Logout',cancelText:'Batal'}))logout()}
const navInitials={overview:'OV',clients:'CL',settings:'ST',clientHome:'OV',clientAnalytics:'AN',clientCustomers:'CU',clientPair:'WA',clientKb:'KB',clientOps:'OP',clientSettings:'ST'};
function navBtn(id,label){return `<button onclick="route('${id}')" id="nav-${id}" data-short="${navInitials[id]||label.slice(0,2).toUpperCase()}"><span class="nav-label">${label}</span></button>`}function activeNav(id){document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));$('nav-'+id)?.classList.add('active')}
function showApp(){role=role||sessionStorage.mbRole;document.body.classList.toggle('admin-mode',role==='admin');document.body.classList.toggle('client-mode',role!=='admin');$('login').classList.add('hidden');$('app').classList.remove('hidden');$('nav').innerHTML=role==='admin'?[navBtn('overview','Overview'),navBtn('clients','Clients'),navBtn('settings','Settings')].join(''):[navBtn('clientHome','Overview'),navBtn('clientAnalytics','Analytics'),navBtn('clientCustomers','Customers'),navBtn('clientPair','WhatsApp'),navBtn('clientKb','Knowledge'),navBtn('clientOps','Operasional'),navBtn('clientSettings','Settings')].join('');route(role==='admin'?'overview':'clientHome')}
async function route(id){try{if(role==='admin'&&id==='kb')id='clients';activeNav(id);setRouteLoading(id);await ({overview,clients:clientsView,settings,clientHome,clientAnalytics,clientCustomers,clientPair,clientKb,clientOps,clientSettings}[id])()}catch(e){toast(e.message)}}
function serviceLabel(v){const x=String(v||'').trim();return x&&x!=='unknown'?x:'inactive'}
function statusPill(s){return `<span class="pill ${esc(s)}">${esc(s)}</span>`}function kbSections(){return ['Identitas Bisnis','Ringkasan Bisnis','Produk / Jasa Utama','Daftar Harga Resmi','Promo / Diskon','Cara Order','Pembayaran','Pengiriman / Delivery / Aktivasi','Jam Operasional','Kebijakan Refund / Garansi / Komplain','FAQ Customer','Gaya Bahasa Bot','Standar Balasan Ideal','Eskalasi ke Admin','Catatan Internal Admin','Batasan Bot','Lead Qualification','Follow Up','Handoff Admin','Data Order','Troubleshooting']}
function kbScore(text){const t=String(text||'');const low=t.toLowerCase();const sections=kbSections();const hits=sections.map(x=>({name:x,ok:low.includes(('## '+x).toLowerCase())||low.includes(x.toLowerCase())}));const filled=t.replace(/\s/g,'').length;const price=/rp\s?\d|harga\s*:|daftar harga/i.test(t);const order=/cara order|alur order|pemesanan|data order/i.test(t);const pay=/transfer|qris|pembayaran|rekening|payment/i.test(t);const policy=/refund|garansi|komplain|retur/i.test(t);const faq=(t.match(/^###\s*Q:/gmi)||[]).length;const replyStandards=/standar balasan|customer:/i.test(t);const escalation=/eskalasi|admin|handoff/i.test(t);let score=Math.round((hits.filter(x=>x.ok).length/sections.length)*55);score+=filled>5000?12:filled>3000?9:filled>1500?5:2;score+=price?5:0;score+=order?5:0;score+=pay?5:0;score+=policy?5:0;score+=faq>=5?5:faq>=2?3:0;score+=replyStandards?4:0;score+=escalation?4:0;return {score:Math.min(100,score),hits,filled,price,order,pay,policy,faq,replyStandards,escalation,missing:hits.filter(x=>!x.ok).map(x=>x.name)}}
function renderKbTools(text){const q=kbScore(text);return `<div class="card kb-tools"><h3>Kualitas Knowledge</h3><div class="score">${q.score}%</div><p class="muted">Target minimal 90% supaya bot lebih pintar dan aman.</p><div class="metric-row"><span>Panjang data</span><b>${q.filled} karakter</b></div><div class="metric-row"><span>FAQ</span><b>${q.faq} item</b></div><div class="metric-row"><span>Harga</span><b>${q.price?'Ada':'Belum'}</b></div><div class="metric-row"><span>Cara order</span><b>${q.order?'Ada':'Belum'}</b></div><div class="metric-row"><span>Pembayaran</span><b>${q.pay?'Ada':'Belum'}</b></div><div class="metric-row"><span>Eskalasi</span><b>${q.escalation?'Ada':'Belum'}</b></div></div>`}

function parseKbCards(content=''){const src=String(content||'');const names=kbSections();return names.map(name=>{const re=new RegExp('(^|\\n)##\\s*'+name.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')+'\\s*\\n([\\s\\S]*?)(?=\\n##\\s+|$)','i');const m=src.match(re);return {title:name,body:m?m[2].trim():''}})}
function initKbState(content=''){kbState=parseKbCards(content)}
function renderKbCards(){return kbState.map((x,i)=>`<div class="card kb-edit-card"><div class="kb-card-head"><h3>${esc(x.title)}</h3><span class="tag ${x.body.trim()?'good':'warn'}">${x.body.trim()?'Terisi':'Kosong'}</span></div><textarea data-kb-index="${i}" oninput="kbCardInput(this)" placeholder="Isi ${esc(x.title)} di sini...">${esc(x.body)}</textarea></div>`).join('')}
function kbCardInput(el){const i=Number(el.dataset.kbIndex);if(kbState[i])kbState[i].body=el.value;kbDirty=true;setKbStateLabel('Belum disimpan','dirty');updateKbCardScore()}
function compileKbFromCards(){return kbState.map(x=>`## ${x.title}\n${String(x.body||'').trim()}`).join('\n\n').trim()+"\n"}
function validateKbBeforeSave(content){if(!String(content||'').trim())return 'Knowledge belum boleh kosong.';return ''}
function setKbStateLabel(text,cls='saved'){const el=$('kbSaveState');if(el){el.textContent=text;el.className='kb-save-state '+cls}}
function updateKbCardScore(){const content=compileKbFromCards();const side=$('kbTools');if(side)side.innerHTML=renderKbTools(content);const text=$('kbText');if(text)text.value=content}
async function refreshKbEditor(btn){return withButton(btn,'Memuat...',async()=>{await clientKb();toast('Editor knowledge diperbarui')})}
function checkKbQuality(btn){updateKbCardScore();const q=kbScore(compileKbFromCards());toast('Kualitas knowledge: '+q.score+'%')}
function renderBars(items=[]){const max=Math.max(1,...items.map(x=>Math.max(x.inbound||0,x.replies||0)));const rows=(items||[]).slice(-14);if(!rows.length)return `<div class="chart"><div class="empty-chart"><div><b>Belum ada data grafik</b><p class="muted">Grafik akan muncul setelah ada pesan masuk dan balasan bot.</p></div></div></div>`;return `<div class="chart"><div class="chart-head"><div><b>Aktivitas pesan</b><p class="muted mini" style="margin:4px 0 0">Perbandingan pesan masuk dan balasan bot per hari.</p></div><div class="chart-legend"><span class="legend-item"><span class="legend-dot"></span>Pesan masuk</span><span class="legend-item"><span class="legend-dot reply"></span>Balasan bot</span></div></div><div class="bar-chart">${rows.map(x=>{const inH=Math.max(8,Math.round((x.inbound||0)/max*140));const outH=Math.max(8,Math.round((x.replies||0)/max*140));return `<div class="bar-wrap"><div class="bar-pair"><div class="bar-item"><span class="bar-value">${x.inbound||0}</span><div title="Pesan masuk ${x.inbound||0}" class="bar" style="height:${inH}px"></div></div><div class="bar-item"><span class="bar-value">${x.replies||0}</span><div title="Balasan bot ${x.replies||0}" class="bar reply" style="height:${outH}px"></div></div></div><span class="bar-label">${esc((x.date||'').slice(5))}</span></div>`}).join('')}</div><p class="muted mini chart-note">Angka di atas bar menunjukkan jumlah real. Tinggi bar dinormalisasi supaya tetap rapi walau data hanya satu hari.</p></div>`}
function renderDonut(pct){return `<div class="donut" style="--pct:${Math.max(0,Math.min(100,pct||0))}%"><b>${pct||0}%</b></div>`}
async function loadClients(){clients=(await api('/api/clients')).clients;return clients}
function adminClientTable(items=[]){if(!items.length)return '<div class="empty-state"><b>Belum ada client</b></div>';return `<div class="admin-table-wrap"><table class="admin-client-table"><thead><tr><th>Bisnis</th><th>Status</th><th>WhatsApp</th><th>Kontak</th><th>Pesan</th><th>Balasan</th><th>Reply</th><th>Service</th><th>Aksi</th></tr></thead><tbody>${items.map(adminClientRow).join('')}</tbody></table></div>`}
function adminClientRow(x){const c=x.client,st=x.stats,id=x.identity,p=x.pairing;const connected=p.status==='connected'||id.paired;const archived=c.status==='archived';return `<tr><td class="client-name-cell"><b>${esc(c.name)}</b><span>${esc(c.slug)} · ${esc(c.ownerName||'-')}</span></td><td>${statusPill(c.status)}</td><td><span class="tag ${connected?'good':'bad'}">${connected?'Connected':'Not Ready'}</span><small>${esc(id.number||c.whatsapp||'Nomor belum ada')}</small></td><td><b>${st.contacts}</b></td><td><b>${st.inboundMessages}</b></td><td><b>${st.botReplies}</b></td><td><span class="tag ${st.replyRate>=90?'good':st.replyRate>=70?'warn':'bad'}">${st.replyRate||0}%</span></td><td><span class="tag ${serviceLabel(x.diagnostics.service)==='active'?'good':serviceLabel(x.diagnostics.service)==='failed'?'bad':'warn'}">${esc(serviceLabel(x.diagnostics.service))}</span></td><td><div class="table-actions"><button onclick="editClientModal('${esc(c.slug)}')">Edit</button><button class="secondary" onclick="inspectClientModal('${esc(c.slug)}')">Inspect</button>${archived?`<button class="success" onclick="restoreClient('${esc(c.slug)}')">Aktifkan</button>`:`<button class="danger" onclick="archiveClient('${esc(c.slug)}')">Arsip</button>`}</div></td></tr>`}
function adminClientCard(x){const c=x.client,st=x.stats,id=x.identity,p=x.pairing;const connected=p.status==='connected'||id.paired;return `<div class="admin-client-card"><div class="admin-client-head"><div><h3>${esc(c.name)}</h3><p class="muted" style="margin:4px 0 0">${esc(c.slug)} · ${esc(c.ownerName||'-')}</p></div>${statusPill(c.status)}</div><div class="admin-status-line"><span class="tag ${connected?'good':'bad'}">WA ${connected?'Connected':'Not Ready'}</span><span class="tag">${esc(id.number||c.whatsapp||'Nomor belum ada')}</span><span class="tag ${st.replyRate>=90?'good':st.replyRate>=70?'warn':'bad'}">Reply ${st.replyRate||0}%</span></div><div class="admin-metrics"><div class="admin-metric"><span>Kontak</span><b>${st.contacts}</b></div><div class="admin-metric"><span>Masuk</span><b>${st.inboundMessages}</b></div><div class="admin-metric"><span>Balasan</span><b>${st.botReplies}</b></div><div class="admin-metric"><span>Belum</span><b>${st.unrepliedMessages||0}</b></div></div><div class="connected-details"><div class="connected-row"><span>Nomor QR</span><b>${esc(id.number||'-')}</b></div><div class="connected-row"><span>Nama WA</span><b>${esc(id.name||'-')}</b></div><div class="connected-row"><span>Service</span><b>${esc(x.diagnostics.service||'-')}</b></div></div><div class="admin-actions"><button onclick="fillClient('${esc(c.slug)}')">Edit Client</button><button class="secondary" onclick="adminInspect('${esc(c.slug)}')">Inspect</button><button class="danger" onclick="archiveClient('${esc(c.slug)}')">Arsip</button></div></div>`}
function closeModal(){modalRoot.className='hidden';modalRoot.innerHTML=''}
function editClientModal(slug){const c=clients.find(x=>x.slug===slug);if(!c){toast('Client tidak ditemukan');return}modalRoot.className='modal-backdrop';modalRoot.innerHTML=`<div class="modal modal-wide admin-edit-modal"><div class="modal-head"><div><span class="settings-kicker">Edit Client</span><h3>${esc(c.name||c.slug)}</h3><p class="muted">Ubah data tenant tanpa pindah halaman.</p></div><button class="ghost modal-x" onclick="closeModal()">×</button></div><input id="mSlug" type="hidden" value="${esc(c.slug)}"><div class="modal-form-grid"><div class="field"><label>Nama Bisnis</label><input id="mName" value="${esc(c.name||'')}"></div><div class="field"><label>Slug</label><input id="mSlugShow" value="${esc(c.slug)}" disabled></div><div class="field"><label>Owner</label><input id="mOwner" value="${esc(c.ownerName||'')}"></div><div class="field"><label>WhatsApp</label><input id="mWa" value="${esc(c.whatsapp||'')}"></div><div class="field"><label>Status</label><select id="mStatus"><option ${c.status==='draft'?'selected':''}>draft</option><option ${c.status==='active'?'selected':''}>active</option><option ${c.status==='paused'?'selected':''}>paused</option><option ${c.status==='archived'?'selected':''}>archived</option></select></div><div class="field"><label>Password Baru</label><input id="mPass" placeholder="kosong = tidak diganti"></div><div class="field modal-notes"><label>Catatan Admin</label><textarea id="mNotes">${esc(c.notes||'')}</textarea></div></div><div class="modal-actions"><button class="ghost" onclick="closeModal()">Batal</button><button onclick="saveClientModal(this)">Simpan Perubahan</button></div></div>`}
async function saveClientModal(btn){return withButton(btn,'Menyimpan...',async()=>{const slug=mSlug.value;await api('/api/clients/'+slug,{method:'PATCH',body:JSON.stringify({name:mName.value,ownerName:mOwner.value,whatsapp:mWa.value,package:'muy-business',status:mStatus.value,notes:mNotes.value,clientPassword:mPass.value})});toast('Client diperbarui');closeModal();await route('clients')})}
async function inspectClientModal(slug){const d=await api('/api/clients/'+slug+'/dashboard');const c=d.client,st=d.stats,id=d.identity,p=d.pairing,diag=d.diagnostics;modalRoot.className='modal-backdrop';modalRoot.innerHTML=`<div class="modal modal-wide inspect-modal"><div class="modal-head"><div><span class="settings-kicker">Inspect</span><h3>${esc(c.name)}</h3><p class="muted">Ringkasan teknis dan operasional client.</p></div><button class="ghost modal-x" onclick="closeModal()">×</button></div><div class="inspect-grid"><div class="metric-row"><span>Status Client</span><b>${esc(c.status)}</b></div><div class="metric-row"><span>Slug</span><b>${esc(c.slug)}</b></div><div class="metric-row"><span>Owner</span><b>${esc(c.ownerName||'-')}</b></div><div class="metric-row"><span>WhatsApp Data</span><b>${esc(c.whatsapp||'-')}</b></div><div class="metric-row"><span>Pairing</span><b>${esc(p.status||'-')}</b></div><div class="metric-row"><span>Nomor QR</span><b>${esc(id.number||'-')}</b></div><div class="metric-row"><span>Nama WA</span><b>${esc(id.name||'-')}</b></div><div class="metric-row"><span>Service</span><b>${esc(serviceLabel(diag.service))}</b></div><div class="metric-row"><span>Kontak</span><b>${st.contacts||0}</b></div><div class="metric-row"><span>Pesan Masuk</span><b>${st.inboundMessages||0}</b></div><div class="metric-row"><span>Balasan Bot</span><b>${st.botReplies||0}</b></div><div class="metric-row"><span>Belum Terbalas</span><b>${st.unrepliedMessages||0}</b></div><div class="metric-row"><span>Reply Rate</span><b>${st.replyRate||0}%</b></div><div class="metric-row"><span>Aktif Hari Ini</span><b>${st.activeToday||0}</b></div></div><div class="logbox inspect-log">${esc(diag.recent||'Belum ada log terbaru untuk client ini.')}</div><div class="modal-actions"><button class="ghost" onclick="closeModal()">Tutup</button><button onclick="editClientModal('${esc(c.slug)}')">Edit Client</button></div></div>`}
async function adminInspect(slug){return inspectClientModal(slug)}
async function overview(){title.textContent='Admin Overview';subtitle.textContent='Monitoring semua client: WhatsApp, analytics, reply rate, dan kesehatan bot.';const d=await api('/api/admin/dashboard');clients=d.clients.map(x=>x.client);const s=d.summary;view.innerHTML=`<div class="admin-health overview-kpis"><div class="kpi kpi-service"><small>Service Bot</small><b>${esc(d.service)}</b></div><div class="kpi kpi-purple"><small>Total Client</small><b>${s.total}</b></div><div class="kpi kpi-green"><small>WA Connected</small><b>${s.connected}</b></div><div class="kpi kpi-blue"><small>Kontak</small><b>${s.contacts}</b></div><div class="kpi kpi-pink"><small>Pesan Masuk</small><b>${s.inboundMessages}</b></div><div class="kpi kpi-mint"><small>Balasan Bot</small><b>${s.botReplies}</b></div><div class="kpi kpi-orange"><small>Reply Rate</small><b>${s.replyRate}%</b></div></div><div class="overview-layout"><div class="card overview-chart-card"><h3>Grafik Semua Client</h3>${renderBars(d.daily||[])}</div><div class="card overview-control-card"><h3>Kontrol Admin</h3><div class="actionbar"><button onclick="svc('restart',this)">Restart Bot</button><button class="secondary" onclick="route('clients')">Kelola Client</button></div><div class="softbox" style="margin-top:16px">Dashboard admin sekarang fokus untuk memantau WhatsApp pairing, nomor terhubung, analytics, statistik customer, reply rate, dan kesehatan service bot.</div></div></div><div class="card"><div class="page-title-row"><div><h3>Operational Client Monitor</h3><p class="muted">Tabel monitoring tenant: status WhatsApp, trafik pesan, reply rate, service, dan aksi cepat.</p></div><button class="secondary" onclick="route('overview')">Refresh</button></div>${adminClientTable(d.clients)}</div>`}
async function clientsView(){title.textContent='Clients';subtitle.textContent='Manajemen tenant lengkap dengan status WhatsApp, analytics, reply rate, dan kesehatan service bot.';const dash=await api('/api/admin/dashboard');clients=dash.clients.map(x=>x.client);view.innerHTML=`<div class="clients-admin-page clients-admin-stacked"><div class="card client-form-card client-form-wide"><div class="page-title-row"><div><h3>Tambah / Edit Client</h3><p class="muted">Isi data tenant dalam satu baris rapi. Klik Edit pada tabel untuk mengubah client.</p></div><button class="secondary" onclick="clearClientForm()">Reset Form</button></div><input id="editSlug" type="hidden"><div class="client-form-horizontal"><div class="field"><label>Nama Bisnis</label><input id="fName" placeholder="Nama bisnis"></div><div class="field"><label>Slug</label><input id="fSlug" placeholder="slug-client"></div><div class="field"><label>Paket</label><input id="fPackage" value="Muy Business" disabled></div><div class="field"><label>Owner</label><input id="fOwner" placeholder="Nama owner"></div><div class="field"><label>WhatsApp</label><input id="fWa" placeholder="628..."></div><div class="field"><label>Status</label><select id="fStatus"><option>draft</option><option>active</option><option>paused</option><option>archived</option></select></div><div class="field"><label>Password Client Baru</label><input id="fPass" placeholder="kosong = tidak diganti"></div><div class="field client-notes-field"><label>Catatan Admin</label><textarea id="fNotes" placeholder="Catatan internal admin"></textarea></div><div class="client-form-actions"><button onclick="saveClientForm(this)">Simpan Client</button><button class="secondary" onclick="clearClientForm()">Reset</button></div></div></div><div class="card client-table-card"><div class="page-title-row"><div><h3>Daftar Client Lengkap</h3><p class="muted">Tabel presisi full-width: status, WhatsApp, statistik pesan, reply rate, service, dan aksi.</p></div><button class="secondary" onclick="route('clients')">Refresh</button></div>${adminClientTable(dash.clients)}</div></div>`}
function clearClientForm(){['editSlug','fName','fSlug','fOwner','fWa','fPass','fNotes'].forEach(id=>$(id).value='');fSlug.disabled=false;fPackage.value='Muy Business';fStatus.value='draft'}function fillClient(slug){editClientModal(slug)}
async function saveClientForm(btn){return withButton(btn,'Menyimpan...',async()=>{const body={name:fName.value,slug:fSlug.value,ownerName:fOwner.value,whatsapp:fWa.value,package:'muy-business',status:fStatus.value,notes:fNotes.value,clientPassword:fPass.value};try{if(editSlug.value){await api('/api/clients/'+editSlug.value,{method:'PATCH',body:JSON.stringify(body)});toast('Client diperbarui')}else{const r=await api('/api/clients',{method:'POST',body:JSON.stringify(body)});toast('Client dibuat. Password: '+r.clientPassword)}clearClientForm();await clientsView()}catch(e){toast(e.message)}})}
async function archiveClient(slug){if(!await confirmBox({title:'Arsipkan client?',message:'Client akan disembunyikan dari status aktif, tapi data tenant tetap aman sebagai arsip.',confirmText:'Arsipkan',danger:true}))return;await api('/api/clients/'+slug,{method:'DELETE'});toast('Client diarsipkan');await route('clients')}async function restoreClient(slug){if(!await confirmBox({title:'Aktifkan kembali client?',message:'Status client akan dikembalikan dari archived ke active.',confirmText:'Aktifkan'}))return;await api('/api/clients/'+slug,{method:'PATCH',body:JSON.stringify({status:'active'})});toast('Client diaktifkan kembali');await route('clients')}function adminOpen(slug){selected=slug;route('clients')}
async function settings(){title.textContent='Admin Settings';subtitle.textContent='Kontrol service, akses admin, dan kesehatan dashboard.';await wait(450);const st=await api('/api/service/status').catch(()=>({service:'inactive',enabled:'disabled',unit:'openclaw-business.service',recent:'Status belum bisa dibaca. Klik Refresh untuk cek ulang.'}));const live=st.service==='active';view.innerHTML=`<div class="settings-admin-page"><div class="card settings-hero"><div><span class="settings-kicker">System Control</span><h3>Kontrol Service Bot</h3><p class="muted">Start, restart, stop, dan cek status unit bot bisnis dari dashboard admin.</p></div><div class="service-badge ${live?'good':'bad'}"><small>Status</small><b id="svcState">${esc(serviceLabel(st.service))}</b></div></div><div class="settings-grid-pro"><div class="card service-control-card"><div class="page-title-row"><div><h3>Service Actions</h3><p class="muted">Unit: <b>${esc(st.unit||'openclaw-business.service')}</b> · Auto-start: <b>${esc(st.enabled||'disabled')}</b></p></div><button class="secondary" onclick="refreshSvcStatus(this)">Refresh</button></div><div class="service-actions"><button class="success" onclick="svc('start',this)"><span>Start</span><small>Nyalakan bot</small></button><button onclick="svc('restart',this)"><span>Restart</span><small>Muat ulang aman</small></button><button class="danger" onclick="svc('stop',this)"><span>Stop</span><small>Matikan sementara</small></button></div><div class="service-status-panel"><div class="metric-row"><span>Status terakhir</span><b id="svcStatusText">${esc(serviceLabel(st.service))}</b></div><div class="metric-row"><span>Auto-start</span><b>${esc(st.enabled||'disabled')}</b></div><div class="metric-row"><span>Update</span><b id="svcUpdated">Baru dicek</b></div></div><div class="logbox service-log" id="svcLog">${esc(st.recent||'Belum ada log service.')}</div></div><div class="card admin-access-card"><div class="page-title-row"><div><h3>Akses Admin</h3><p class="muted">Ganti username/password admin dengan validasi password lama.</p></div></div><div class="field"><label>Username admin baru (opsional)</label><input id="newAdminUser" autocomplete="username" placeholder="kosong = tidak diganti"></div><div class="field"><label>Password lama</label><input id="oldPass" type="password" autocomplete="current-password"></div><div class="field"><label>Password baru</label><input id="newPass" type="password" autocomplete="new-password"></div><button onclick="changeAdminPassword(this)">Simpan Akses Admin</button></div></div><div class="card settings-checklist"><h3>Checklist Operasional</h3><div class="insight-grid"><div class="feature-card"><h4>Start</h4><p class="muted">Menyalakan unit jika bot sedang inactive/failed.</p></div><div class="feature-card"><h4>Restart</h4><p class="muted">Dipakai setelah ubah konfigurasi, pairing, atau bot tidak membalas.</p></div><div class="feature-card"><h4>Stop</h4><p class="muted">Mematikan bot sementara. Dashboard akan menampilkan proses stopping.</p></div></div></div></div>`}
async function refreshSvcStatus(btn){return withButton(btn,'Mengecek...',async()=>{const st=await api('/api/service/status');if($('svcState'))$('svcState').textContent=serviceLabel(st.service);if($('svcStatusText'))$('svcStatusText').textContent=serviceLabel(st.service);if($('svcUpdated'))$('svcUpdated').textContent=new Date().toLocaleTimeString('id-ID');if($('svcLog'))$('svcLog').textContent=st.recent||'Belum ada log service.';toast('Status service diperbarui')})}
async function svc(a,btn){return withButton(btn,(a==='restart'?'Restarting...':a==='start'?'Starting...':'Stopping...'),async()=>{if(a==='stop'&&!await confirmBox({title:'Stop bot bisnis?',message:'Bot tidak akan membalas sampai dinyalakan lagi dari service/terminal atau dashboard bila masih aktif.',confirmText:'Stop Bot',danger:true}))return;const r=await api('/api/service/'+a,{method:'POST'});toast(a==='restart'?'Restart dikirim':a==='start'?'Start dikirim':'Stop dikirim');setTimeout(()=>refreshSvcStatus(null).catch(()=>{}),a==='restart'?1800:900);if($('svcStatusText'))$('svcStatusText').textContent=serviceLabel(r.service)||'processing';if($('svcState'))$('svcState').textContent=serviceLabel(r.service)||'processing'})}
async function changeAdminPassword(btn){return withButton(btn,'Mengganti...',async()=>{await api('/api/auth/admin/password',{method:'POST',body:JSON.stringify({username:newAdminUser.value,currentPassword:oldPass.value,newPassword:newPass.value})});toast('Password diganti');setTimeout(logout,1200)})}
async function clientHome(){title.textContent='Client Dashboard';subtitle.textContent='Analytics WhatsApp, performa bot, nomor pairing, dan kesehatan operasional.';const slug=sessionStorage.mbSlug;const d=await api('/api/clients/'+slug+'/dashboard');const c=d.client,pair=d.pairing,id=d.identity,st=d.stats,diag=d.diagnostics;view.innerHTML=`<div class="grid"><div class="card stat"><small>Bisnis</small><b>${esc(c.name)}</b></div><div class="card stat"><small>Nomor Pairing</small><b style="font-size:23px">${esc(id.number||'Belum terhubung')}</b></div><div class="card stat"><small>Orang Dibalas</small><b>${st.repliedContacts}</b></div><div class="card stat"><small>Reply Rate</small><b>${st.replyRate||0}%</b></div></div><div class="two"><div class="card"><h3>Grafik Pesan 14 Hari</h3>${renderBars(st.daily||[])}</div><div class="card"><h3>Rasio Balasan Bot</h3><div style="display:grid;place-items:center;margin:16px 0">${renderDonut(st.replyRate||0)}</div><div class="insight-grid"><div class="feature-card"><h4>Pesan Masuk</h4><b>${st.inboundMessages}</b></div><div class="feature-card"><h4>Balasan Bot</h4><b>${st.botReplies}</b></div><div class="feature-card"><h4>Belum Terbalas</h4><b>${st.unrepliedMessages||0}</b></div><div class="feature-card"><h4>Kontak Unik</h4><b>${st.contacts}</b></div></div></div></div><div class="two"><div class="card"><h3>Detail WhatsApp</h3><div class="identity-grid"><div class="metric-row"><span>Status Pairing</span><b>${esc(pair.status)}</b></div><div class="metric-row"><span>Nomor Client di Data</span><b>${esc(c.whatsapp||'-')}</b></div><div class="metric-row"><span>Nomor Terhubung QR</span><b>${esc(id.number||'-')}</b></div><div class="metric-row"><span>Nama WhatsApp</span><b>${esc(id.name||'-')}</b></div><div class="metric-row"><span>Platform</span><b>${esc(id.platform||'-')}</b></div><div class="metric-row"><span>Service Bot</span><b>${esc(diag.service)}</b></div></div><div class="actionbar"><button onclick="route('clientPair')">Buka Pairing</button><button class="secondary" onclick="route('clientHome')">Refresh Data</button></div></div><div class="card"><h3>Insight Operasional</h3><div class="feature-card"><h4>Kesehatan Bot</h4><p class="muted">${diag.service==='active'&&pair.status==='connected'?'Bot aktif dan WhatsApp terhubung.':'Perlu cek pairing/service sebelum live.'}</p></div><div class="feature-card"><h4>Catatan Validasi</h4><p class="muted">Untuk validasi live, gunakan nomor customer/admin nyata yang memang disetujui.</p></div><div class="feature-card"><h4>Rekomendasi</h4><p class="muted">Lengkapi knowledge sampai minimal 90%, terutama harga, pembayaran, order, dan kebijakan.</p></div></div></div><div class="two"><div class="card"><h3>Top Kontak / Nomor Dibalas</h3>${(st.topContacts||st.conversations||[]).length?(st.topContacts||st.conversations).map(x=>`<div class="conversation"><b>${esc(x.contact)}</b><p class="muted mini">Masuk: ${x.inbound} · Dibalas: ${x.outbound} · Belum: ${x.unreplied||0}</p><p><b class="mini">Pesan terakhir</b>${esc(x.lastUserText||'-')}</p><p><b class="mini">Balasan terakhir</b>${esc(x.lastBotText||'-')}</p></div>`).join(''):'<p class="muted">Belum ada percakapan yang tercatat.</p>'}</div><div class="card"><h3>Diagnostik Bot</h3><p class="muted">Dipakai untuk cek penyebab bot tidak membalas atau session WhatsApp bermasalah.</p><div class="softbox"><b>Provider</b><br><span class="mono">${esc(diag.providerLine||'Belum ada provider WhatsApp aktif di log terbaru.')}</span></div><div class="logbox" style="margin-top:12px">${esc(diag.recent||'Belum ada log WhatsApp terbaru.')}</div></div></div><div class="three"><div class="card"><h3>Knowledge Base</h3><p class="muted">Lengkapi data bisnis sampai detail agar bot tidak mengarang dan jawabannya makin pintar.</p><button onclick="route('clientKb')">Edit Knowledge</button></div><div class="card"><h3>Operasional</h3><p class="muted">Checklist kesiapan, standar balasan, validasi, dan handoff admin.</p><button onclick="route('clientOps')">Buka Operasional</button></div><div class="card"><h3>Perbaikan Cepat</h3><p class="muted">Jika tidak ada balasan, cek status pairing, service, log inbound, dan coba dari nomor berbeda.</p><button onclick="route('clientPair')">Cek WhatsApp</button></div></div>`}
function fmtDate(x){if(!x)return '-';try{return new Date(x).toLocaleString('id-ID')}catch{return x}}
function pctClass(p){return p>=90?'good':p>=70?'warn':'bad'}
function exportCustomersCsv(){const rows=window.__customerRows||[];const csv=['Nomor,Masuk,Dibalas,Belum,Pesan Terakhir,Balasan Terakhir'].concat(rows.map(r=>[r.contact,r.inbound,r.outbound,r.unreplied||0,r.lastUserText||'',r.lastBotText||''].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(','))).join('\n');const blob=new Blob([csv],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='muy-business-customers.csv';a.click();URL.revokeObjectURL(a.href)}
function renderCustomerCards(rows){return rows.length?`<div class="customer-list">${rows.map((x,i)=>`<div class="customer-card"><div class="customer-card-head"><div><b>${esc(x.contact)}</b><div class="muted mini">Terakhir masuk: ${esc(fmtDate(x.lastInbound))}</div></div><div class="export-actions"><button class="secondary" onclick="navigator.clipboard?.writeText('${esc(x.contact)}');toast('Nomor disalin')">Copy Nomor</button></div></div><div class="customer-meta"><span class="tag">Masuk ${x.inbound}</span><span class="tag good">Dibalas ${x.outbound}</span><span class="tag ${(x.unreplied||0)>0?'bad':'good'}">Belum ${x.unreplied||0}</span><span class="tag warn">#${i+1}</span></div><div class="customer-preview"><div class="preview-box"><b>Pesan Terakhir</b>${esc(x.lastUserText||'-')}</div><div class="preview-box"><b>Balasan Terakhir Bot</b>${esc(x.lastBotText||'-')}</div></div></div>`).join('')}</div>`:'<div class="empty-state"><b>Belum ada data customer</b><p class="muted">Data akan muncul setelah ada chat WhatsApp masuk.</p></div>'}
function filterCustomers(){const q=(customerSearch?.value||'').toLowerCase();const mode=customerFilter?.value||'all';let rows=[...(window.__customerRows||[])];if(q)rows=rows.filter(r=>String(r.contact).toLowerCase().includes(q)||String(r.lastUserText).toLowerCase().includes(q)||String(r.lastBotText).toLowerCase().includes(q));if(mode==='unreplied')rows=rows.filter(r=>(r.unreplied||0)>0);if(mode==='replied')rows=rows.filter(r=>(r.outbound||0)>0);if(mode==='active')rows=rows.filter(r=>(r.inbound+r.outbound)>=2);customersList.innerHTML=renderCustomerCards(rows)}
async function clientAnalytics(){title.textContent='Analytics';subtitle.textContent='Monitoring performa WhatsApp bot, reply rate, tren pesan, dan kesehatan layanan.';const slug=sessionStorage.mbSlug;const d=await api('/api/clients/'+slug+'/dashboard');const st=d.stats;const health=pctClass(st.replyRate||0);view.innerHTML=`<div class="kpi-row"><div class="kpi"><small>Reply Rate</small><b>${st.replyRate||0}%</b></div><div class="kpi"><small>Pesan Masuk</small><b>${st.inboundMessages}</b></div><div class="kpi"><small>Balasan Bot</small><b>${st.botReplies}</b></div><div class="kpi"><small>Belum Terbalas</small><b>${st.unrepliedMessages||0}</b></div><div class="kpi"><small>Aktif 24 Jam</small><b>${st.activeToday||0}</b></div></div><div class="two"><div class="card"><h3>Grafik Pesan 14 Hari</h3>${renderBars(st.daily||[])}</div><div class="card"><h3>Rasio Balasan</h3><div style="display:grid;place-items:center;margin:18px 0">${renderDonut(st.replyRate||0)}</div><div class="insight-card ${health}"><b>Status Performa</b><p class="muted">${health==='good'?'Sangat baik. Bot membalas mayoritas pesan.':health==='warn'?'Cukup baik, tapi masih ada pesan yang perlu dicek.':'Perlu perhatian. Banyak pesan belum terbalas atau data belum stabil.'}</p></div></div></div><div class="health-grid"><div class="insight-card"><b>Terakhir Pesan Masuk</b><p class="muted">${esc(fmtDate(st.lastInboundAt))}</p></div><div class="insight-card"><b>Terakhir Bot Membalas</b><p class="muted">${esc(fmtDate(st.lastReplyAt))}</p></div><div class="insight-card"><b>Rata-rata Pesan/Kontak</b><p class="muted">${st.avgInboundPerContact||0} pesan per kontak</p></div></div><div class="two"><div class="card"><h3>Kontak Paling Aktif</h3>${renderCustomerCards(st.topContacts||[])}</div><div class="card"><h3>Perlu Dicek</h3>${renderCustomerCards(st.unrepliedConversations||[])}</div></div>`}
async function clientCustomers(){title.textContent='Customers';subtitle.textContent='CRM ringan untuk melihat customer, status balasan, dan pesan terakhir.';const slug=sessionStorage.mbSlug;const d=await api('/api/clients/'+slug+'/dashboard');window.__customerRows=d.stats.conversations||[];view.innerHTML=`<div class="kpi-row"><div class="kpi"><small>Total Kontak</small><b>${d.stats.contacts}</b></div><div class="kpi"><small>Sudah Dibalas</small><b>${d.stats.repliedContacts}</b></div><div class="kpi"><small>Belum Terbalas</small><b>${d.stats.unrepliedMessages||0}</b></div><div class="kpi"><small>Pesan Masuk</small><b>${d.stats.inboundMessages}</b></div><div class="kpi"><small>Balasan Bot</small><b>${d.stats.botReplies}</b></div></div><div class="card"><div class="customer-toolbar"><div class="row"><input id="customerSearch" placeholder="Cari nomor / pesan / balasan" oninput="filterCustomers()"><select id="customerFilter" onchange="filterCustomers()"><option value="all">Semua customer</option><option value="unreplied">Belum terbalas</option><option value="replied">Sudah dibalas</option><option value="active">Aktif</option></select></div><div class="export-actions"><button class="secondary" onclick="exportCustomersCsv()">Export CSV</button><button onclick="route('clientCustomers')">Refresh</button></div></div><div id="customersList">${renderCustomerCards(window.__customerRows)}</div></div>`}
async function clientSettings(){title.textContent='Settings';subtitle.textContent='Pengaturan dan status teknis client.';const slug=sessionStorage.mbSlug;const d=await api('/api/clients/'+slug+'/dashboard');view.innerHTML=`<div class="settings-grid"><div class="card"><h3>Profil Bisnis</h3><table class="mini-table"><tr><td>Nama</td><td>${esc(d.client.name)}</td></tr><tr><td>Slug</td><td>${esc(d.client.slug)}</td></tr><tr><td>Nomor data</td><td>${esc(d.client.whatsapp||'-')}</td></tr><tr><td>Paket</td><td>Muy Business</td></tr></table></div><div class="card"><h3>Status WhatsApp</h3><table class="mini-table"><tr><td>Pairing</td><td>${esc(d.pairing.status)}</td></tr><tr><td>Nomor QR</td><td>${esc(d.identity.number||'-')}</td></tr><tr><td>Nama WA</td><td>${esc(d.identity.name||'-')}</td></tr><tr><td>Service</td><td>${esc(d.diagnostics.service)}</td></tr></table><div class="actionbar"><button onclick="route('clientPair')">Kelola WhatsApp</button><button class="secondary" onclick="route('clientSettings')">Refresh</button></div></div><div class="card"><h3>Panduan Aman</h3><p class="muted">Jangan simpan password, OTP, token, atau data rahasia di knowledge. Simpan hanya informasi bisnis yang aman dipakai bot menjawab customer.</p></div><div class="card"><h3>Maintenance</h3><p class="muted">Update knowledge setiap ada perubahan harga, promo, stok, jam operasional, rekening, atau kebijakan.</p></div></div>`}
function renderQrBlock(p, connected=false){if(connected)return '<div class="connected-box"><span class="connection-badge">Terhubung</span><div><div class="connected-title">WhatsApp Sudah Terhubung</div><div class="connected-sub">Nomor WhatsApp client sudah berhasil pairing. QR code disembunyikan agar tidak membingungkan.</div></div></div>';if(p.qr)return p.qrType==='image'?`<img src="${p.qr}" style="max-width:260px;width:100%;height:auto;border:3px solid #111;border-radius:16px;box-shadow:3px 3px 0 #111;background:#fff;padding:10px">`:p.qrType==='svg'?p.qr:`<div class="qrtext">${esc(p.qr)}</div>`;if(p.status==='preparing')return '<div class="qr-loading"><b>Menyiapkan QR...</b><p class="muted">Biasanya 3-10 detik. Dashboard update otomatis.</p></div>';if(p.status==='failed')return `<div class="qr-loading"><b>QR gagal dibuat</b><p class="muted">${esc(p.note||'Klik Refresh QR untuk mencoba ulang.')}</p></div>`;return '<div class="qr-loading"><b>QR belum tersedia</b><p class="muted">Klik Refresh QR untuk membuat QR baru.</p></div>'}
async function updatePairingOnly(){const slug=sessionStorage.mbSlug;const p=await api('/api/clients/'+slug+'/pairing');const box=document.querySelector('.qrbox');const row=document.querySelector('.pairing-status-row');const note=document.querySelector('#pairNote');if(row)row.innerHTML=statusPill(p.status);if(note)note.textContent=p.note||'';if(box){box.classList.toggle('loading',p.status==='preparing');box.innerHTML=renderQrBlock(p,false)}return p}
async function clientPair(){title.textContent='WhatsApp Pairing';subtitle.textContent='Hubungkan WhatsApp client dengan QR code yang fresh dan aman.';const slug=sessionStorage.mbSlug;const [p,d]=await Promise.all([api('/api/clients/'+slug+'/pairing'),api('/api/clients/'+slug+'/dashboard')]);const connected=p.status==='connected'||d.identity.paired;let qr;if(connected){qr=`<div class="connected-box"><span class="connection-badge">Terhubung</span><div><div class="connected-title">WhatsApp Sudah Terhubung</div><div class="connected-sub">Nomor WhatsApp client sudah berhasil pairing. QR code disembunyikan agar tidak membingungkan dan mencegah scan ulang yang tidak diperlukan.</div></div><div class="connected-details"><div class="connected-row"><span>Nomor Terhubung</span><b>${esc(d.identity.number||'-')}</b></div><div class="connected-row"><span>Nama Akun</span><b>${esc(d.identity.name||'-')}</b></div><div class="connected-row"><span>Platform</span><b>${esc(d.identity.platform||'-')}</b></div><div class="connected-row"><span>Service Bot</span><b>${esc(d.diagnostics.service||'-')}</b></div></div><div class="qr-status-note">Jika ingin mengganti nomor WhatsApp, klik Putuskan terlebih dahulu, lalu buat QR baru.</div></div>`}else{qr=renderQrBlock(p,false)}view.innerHTML=`<div class="two"><div class="card"><h3>Status Koneksi</h3><div class="status-row pairing-status-row">${statusPill(connected?'connected':p.status)}</div><div id="pairNote" class="softbox" style="margin-top:14px">${esc(connected?'WhatsApp sudah terhubung dan siap menerima pesan customer. QR code tidak ditampilkan karena session aktif.':p.note)}</div><div class="identity-grid"><div class="metric-row"><span>Nomor client</span><b>${esc(d.client.whatsapp||'-')}</b></div><div class="metric-row"><span>Nomor terhubung QR</span><b>${esc(d.identity.number||'-')}</b></div><div class="metric-row"><span>Nama WhatsApp</span><b>${esc(d.identity.name||'-')}</b></div></div><ul class="step-list"><li>1. Klik Refresh QR untuk membuat QR baru.</li><li>2. Tunggu QR muncul, biasanya beberapa detik.</li><li>3. Scan segera dari WhatsApp perangkat client.</li><li>4. Kalau ingin ganti nomor, klik Putuskan lalu pairing ulang.</li></ul><div class="actionbar"><button onclick="refreshPair(this)">${connected?'Buat QR Baru' :'Refresh QR'}</button><button class="danger" onclick="disconnectPair(this)">Putuskan</button></div></div><div class="card"><h3>${connected?'Status WhatsApp':'QR Code WhatsApp'}</h3><div class="qrbox ${connected?'connected':''}">${qr}</div><div class="qr-help"><p class="muted">${connected?'Session WhatsApp aktif. Bot akan memakai nomor terhubung ini untuk menerima dan membalas pesan customer.':'Gunakan QR terbaru. Jika gagal, klik Putuskan lalu Refresh QR lagi.'}</p>${connected?'':'<p class="muted">QR WhatsApp cepat kadaluarsa, jadi scan segera setelah muncul.</p>'}</div></div></div>`}
async function refreshPair(btn){return withButton(btn,'Memulai...',async()=>{const slug=sessionStorage.mbSlug;const box=document.querySelector('.qrbox');if(box){box.classList.add('loading');box.innerHTML='<div class="qr-loading"><b>Menyiapkan QR...</b><p class="muted">Request sudah masuk. QR akan muncul otomatis.</p></div>'}await api('/api/clients/'+slug+'/pairing/refresh',{method:'POST'});let p;for(let i=0;i<20;i++){await wait(i<6?1000:2000);p=await updatePairingOnly();if(p.qr||['connected','failed'].includes(p.status))break}if(p&&p.status==='connected')await clientPair()})}
async function disconnectPair(btn){if(await confirmBox({title:'Putuskan WhatsApp?',message:'Session lokal tenant akan dilepas jika tersedia.',confirmText:'Putuskan',danger:true})){return withButton(btn,'Memutuskan...',async()=>{const m=loadingMeta.disconnect;setViewLoading(m[1],m[2],m[0]);await api('/api/clients/'+sessionStorage.mbSlug+'/pairing/disconnect',{method:'POST'});await clientPair()})}}
async function clientKb(){title.textContent='Knowledge Base';subtitle.textContent='Isi knowledge per-card agar lebih mudah dipahami. Semua bagian ini dipakai bot untuk menjawab customer.';const slug=sessionStorage.mbSlug;const d=await api('/api/clients/'+slug+'/kb');kbOriginalContent=d.content;kbDirty=false;initKbState(d.content);view.innerHTML=`<div class="page-title-row"><div><b>Mode Card Editor</b><p class="muted" style="margin:4px 0 0">Isi tiap kartu sesuai topiknya. Section bisa ditambah, dihapus, dikosongkan, atau diisi manual.</p></div><div class="kb-actionbar"><button onclick="saveClientKb(this)">Simpan Semua</button><button class="secondary" onclick="refreshKbEditor(this)">Refresh Editor</button><button class="secondary" onclick="checkKbQuality(this)">Cek Kualitas</button><span id="kbSaveState" class="kb-save-state saved">Tersimpan</span></div></div><div class="kb-editor-layout"><div class="kb-card-grid" id="kbCards">${renderKbCards()}</div><div class="kb-side" id="kbTools"></div></div><textarea id="kbText" class="hidden"></textarea>`;kbText.value=d.content;updateKbCardScore()}
async function saveClientKb(btn){return withButton(btn,'Menyimpan...',async()=>{const content=compileKbFromCards();const err=validateKbBeforeSave(content);if(err){setKbStateLabel('Perlu dilengkapi','error');toast(err);return}kbText.value=content;const saved=await api('/api/clients/'+sessionStorage.mbSlug+'/kb',{method:'PUT',body:JSON.stringify({content})});if(saved.content&&saved.content!==content){initKbState(saved.content);kbCards.innerHTML=renderKbCards();content=saved.content}kbOriginalContent=content;kbDirty=false;setKbStateLabel('Tersimpan', 'saved');updateKbCardScore();toast('Knowledge tersimpan')})}
async function clientOps(){title.textContent='Operasional Bot';subtitle.textContent='Panduan operasional lengkap, kualitas knowledge, grafik performa, dan checklist live.';const slug=sessionStorage.mbSlug;const d=await api('/api/clients/'+slug+'/dashboard');const kb=(await api('/api/clients/'+slug+'/kb')).content;const q=kbScore(kb);view.innerHTML=`<div class="grid"><div class="card stat"><small>Kualitas Knowledge</small><b>${q.score}%</b></div><div class="card stat"><small>Status Bot</small><b style="font-size:24px">${esc(d.diagnostics.service)}</b></div><div class="card stat"><small>Nomor Pairing</small><b style="font-size:22px">${esc(d.identity.number||'-')}</b></div><div class="card stat"><small>Reply Rate</small><b>${d.stats.replyRate||0}%</b></div></div><div class="two"><div class="card"><h3>Grafik Operasional</h3>${renderBars(d.stats.daily||[])}</div><div class="card"><h3>Kesiapan Live</h3><div style="display:grid;place-items:center;margin:12px 0">${renderDonut(q.score||0)}</div><p class="muted">Target live profesional: knowledge minimal 90%, nomor pairing connected, service active, dan validasi dari nomor nyata yang disetujui berhasil.</p></div></div><div class="ops-safety-layout"><div class="card ops-checklist-card"><h3>Checklist Wajib Sebelum Live</h3><div class="checkitem ${q.price?'ok':'warn'}"><span>Harga resmi lengkap</span><b>${q.price?'Siap':'Belum'}</b></div><div class="checkitem ${q.order?'ok':'warn'}"><span>Cara order jelas</span><b>${q.order?'Siap':'Belum'}</b></div><div class="checkitem ${q.pay?'ok':'warn'}"><span>Pembayaran jelas</span><b>${q.pay?'Siap':'Belum'}</b></div><div class="checkitem ${q.policy?'ok':'warn'}"><span>Kebijakan refund/garansi</span><b>${q.policy?'Siap':'Belum'}</b></div><div class="checkitem ${q.escalation?'ok':'warn'}"><span>Handoff admin</span><b>${q.escalation?'Siap':'Belum'}</b></div></div><div class="ops-rules-stack"><div class="card ops-wide-card ops-safe-card"><h3>Aturan Aman Bot</h3><p class="muted">Bot tidak boleh mengarang harga, stok, promo, garansi, rekening, invoice, atau janji pengiriman. Jika data belum ada, bot harus tanya admin atau minta konfirmasi.</p></div><div class="card ops-wide-card ops-validate-card"><h3>Validasi Wajib</h3><p class="muted">Validasi alur real: harga, cara order, pembayaran, jam buka, promo, stok, komplain, refund, garansi, pengiriman, dan pertanyaan di luar knowledge.</p></div><div class="ops-mini-grid"><div class="card"><h3>Kalimat Eskalasi</h3><p class="muted">Baik kak, untuk bagian ini aku bantu teruskan ke admin supaya jawabannya akurat dan aman ya.</p></div><div class="card"><h3>Standar Balasan</h3><p class="muted">Jawab singkat, natural, ramah, tidak corporate, tidak menyebut sistem internal, dan fokus ke kebutuhan customer.</p></div><div class="card"><h3>Perawatan Harian</h3><p class="muted">Update harga, stok, promo, jam operasional, FAQ, kebijakan, dan cek kontak belum terbalas setiap hari.</p></div></div></div></div><div class="card"><h3>Section Knowledge yang Masih Kurang</h3>${q.missing.length?`<div class="insight-grid">${q.missing.map(x=>`<div class="feature-card"><h4>${esc(x)}</h4><p class="muted">Tambahkan section ini di Knowledge agar bot lebih pintar.</p></div>`).join('')}</div>`:'<p class="muted">Semua section utama sudah ada. Tinggal pastikan isinya benar dan tidak kosong.</p>'}</div>`}
if(auth&&sessionStorage.mbRole){role=sessionStorage.mbRole;showApp()}
